/bin/bash -lc 'site_tmp=$(mktemp -d "$TMPDIR/biyani-specific-pages.XXXXXX")
curl -kfsSL --max-time 30 -A '"'Mozilla/5.0' 'https://biyanigirlscollege.com/page-sitemap.xml' > \""'$site_tmp/pages.xml"
printf '"'%s
' 'SITEMAP_PAGES'
rg -o '<loc>["'^<]+'"' \""'$site_tmp/pages.xml" | sed '"'s#<loc>##' | sed -n '1,240p'
printf '%s
' 'HOME_TEXT'
curl -kfsSL --max-time 30 -A 'Mozilla/5.0' 'https://biyanigirlscollege.com/' > \""'$site_tmp/home.html"
python3 - "$site_tmp/home.html" <<'"'PY'
import re,sys
from html.parser import HTMLParser
from html import unescape
class P(HTMLParser):
 def __init__(self): super().__init__(); self.skip=0; self.o=[]
 def handle_starttag(self,t,a):
  if t in ('script','style','noscript','svg'): self.skip+=1
  if t in ('h1','h2','h3','h4','h5','h6','p','li','br','td','th'): self.o.append('\\n')
 def handle_endtag(self,t):
  if t in ('script','style','noscript','svg') and self.skip:self.skip-=1
  if t in ('h1','h2','h3','h4','h5','h6','p','li','br','td','th'): self.o.append('\\n')
 def handle_data(self,d):
  if not self.skip:self.o.append(d)
p=P();p.feed(open(sys.argv[1],encoding='utf-8',errors='ignore').read())
x=unescape(''.join(p.o));x=re.sub(r'[ \\t\\r\\f\\v]+',' ',x)
ls=[]
for z in x.splitlines():
 z=z.strip()
 if z and (not ls or z"'!=ls[-1]):ls.append(z)
for z in ls:
 if re.search(r'"'Biyani|Jaipur|course|degree|program|college|admission|science|commerce|computer|BCA|B\\.Sc|B\\.Com|M\\.Sc|M\\.Com|BBA|address|eligib|duration',z,re.I):print(z)
PY"

