python3 - "$page_tmp" <<'"'PY'
import os,re,sys
from html import unescape
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self): super().__init__(); self.o=[]; self.skip=0
    def handle_starttag(self,t,a):
        if t in ('script','style','noscript','svg'): self.skip+=1
        if t in ('p','br','li','h1','h2','h3','h4','h5','h6','td','th'): self.o.append(chr(10))
    def handle_endtag(self,t):
        if t in ('script','style','noscript','svg') and self.skip:self.skip-=1
        if t in ('p','br','li','h1','h2','h3','h4','h5','h6','td','th'): self.o.append(chr(10))
    def handle_data(self,d):
        if not self.skip:self.o.append(d)
def clean(s):
    p=P(); p.feed(s)
    x=unescape(''.join(p.o))
    x=re.sub(r'[ \\t\\r\\f\\v]+',' ',x)
    ls=[]
    for z in x.splitlines():
        z=z.strip()
        if z and (not ls or z"'!=ls[-1]): ls.append(z)
    return '"' | '.join(ls)
for fn in sorted(os.listdir(sys.argv[1]), key=lambda x:int(x.split('.')[0])):
    raw=open(os.path.join(sys.argv[1],fn),encoding='utf-8',errors='ignore').read()
    print(chr(10)+'=== '+fn+' ===')
    pat=r'<a class=\"elementor-toggle-title\"["'^>]*>(.*?)</a>'"\\s*</div>\\s*<div["'^>]*class="elementor-tab-content[''^>]*>(.*?)</div>'"'
    found=re.findall(pat,raw,re.S|re.I)
    for title,body in found:
        print('TITLE:',clean(title))
        print('BODY:',clean(body))
        links=re.findall(r'href=\"(["'^"]+)"'"',body,re.I)
        if links: print('LINKS:', ' '.join(unescape(x) for x in links))
PY"

